    //Location type names, for the header. The stage is a roman numeral after them.
    "loctype bright": "bright",
    "loctype dark": "dark",
    "loctype narrow": "narrow",
    "loctype open": "open",
    "loctype thin air": "thin air",
    "loctype eldritch": "eldritch",
    "loctype rough": "rough",
    "loctype wet": "wet",
    "loctype aquatic": "aquatic",
    //LOCATIONS - location type stages.
    "desc loctype bright 1": "A place that's always lit, no matter the time of the day",
    "desc loctype bright 2": "An extremely bright place, excessive light makes it hard to keep eyes open",
    "desc loctype bright 3": "A place with so much light that an average person would go blind in an instant",
    "desc loctype dark 1": "It's dark here, comparable to a bright night",
    "desc loctype dark 2": "An extremely dark place, darker than most of the nights",
    "desc loctype dark 3": "Pure darkness with not even a tiniest flicker of light",
    "desc loctype narrow 1": "A narrow area where there's not much place for maneuvering",
    "desc loctype narrow 2": "A very tight and narrow area where there's not much place for maneuvering",
    "desc loctype narrow 3": "An area so cramped that it's a miracle you can even move",
    "desc loctype narrow 4": "Are you trying to die? One step the wrong way and you fall to your death!",
    "desc loctype open 1": "A completely open area where attacks can come from any direction",
    "desc loctype open 2": "An area that's completely open and simultanously obstructs your view, making it hard to predict where an attack will come from",
    "desc loctype thin air 1": "Place with thinner air, which negatively impacts your body",
    "desc loctype thin air 2": "Place with very thin air, heavily affecting your body",
    "desc loctype eldritch 1": "This place brings a strong sense of unease",
    "desc loctype eldritch 2": "This place goes against the laws of the world",
    "desc loctype rough 1": "The loose sand and jagged rocks make it harder to fight effectively",
    "desc loctype rough 2": "A boggy marshland is a terrible location to fight for your life in",
    "desc loctype rough 3": "The muck somehow causes you to slip even while holding you firmly in place",
    "desc loctype wet 1": "Attempting to stay dry in conditions like this is impossible",
    "desc loctype aquatic 1": "Wading in water up to your knees restricts your movement",
    "desc loctype aquatic 2": "With most of your body submerged, it's hard to move",
    "desc loctype aquatic 3": "Fully underwater and with no ground under your feet, the moves you learned on land will help you little",
    "desc loctype aquatic 4": "Crushed by the immense pressure of the oceanic abyss",

