    "noise Antique store 1": "*Clock ticking*",
    "noise Adventurer's guild 1": "I tell you, I really met her once!",
    "noise Adventurer's guild 2": "Blergh...",
    "noise Adventurer's guild 3": "*Someone falls of a bench after drinking too much*",
    "noise Adventurer's guild 4": "Don't be stupid, everyone knows the world is a cube",
    "noise Adventurer's guild 5": "I wanted to report...",
    "noise Adventurer's guild 6": "Congratulations, that's another task completed!",
    "noise Adventurer's guild 7": "Gonna reach next rank soon, I hope",
    "noise Adventurer's guild 8": "That advancement exam was absurd...",
    "noise Adventurer's guild 9": "After my next dungeon dive, I will seriously ask him to marry me",
    "noise Adventurer's guild 10": "Sorry? What's a death flag?",
    "noise Adventurer's guild 11": "Haha, I did it!",
    "noise Adventurer's guild 12": "With this, I can finally retire! Or maybe... just one more...",
    "noise Adventurer's guild 13": "Anything is better than rats",
    "noise Adventurer's guild 14": "Just one bite and all that was left of my team leader was a pair of bloodied legs... I'm never going back there, no way.",
    "noise Adventurer's guild 15": "Give us drinks, we are celebrating!",
    "noise Adventurer's guild 16": "So, that one time we stumbled upon a pair of bloodied legs, just standing upright in front of a boss chamber...",
    "noise Adventurer's guild 17": "I will never get idiots who dive in the dungeon, it's too risky",
    "noise Adventurer's guild 18": "Personally? I would rather do simple small requests my entire life than risk meeting one of those...",
    "noise Adventurer's guild 19": "Right? And then I deliver it and they say nuh uh, this isn't what we asked for, but it was EXACTLY was they asked for",
    "noise Adventurer's guild 20": "Remember what we talked about last time?",
    "noise Adventurer's guild 21": "Took me a few trips, but I actually saw them...",
    "noise Adventurer's guild 22": "...they maybe just reached adulthood, and yet...",
    "noise Adventurer's guild 23": "...they were just rushing through floor after floor...",
    "noise Adventurer's guild 24": "...every spear stab was a kill...",
    "noise Adventurer's guild 25": "...every sword swing was a kill...",
    "noise Adventurer's guild 26": "...every strange spell was a kill...",
    "noise Adventurer's guild 27": "...and they really were strange...",
    "noise Adventurer's guild 28": "...I'm serious, I've never seen magic like that...",
    "noise Adventurer's guild 29": "...it was as if shadows were alive...",
    "noise Adventurer's guild 30": "...actually, while I didn't see that one...",
    "noise Adventurer's guild 31": "...my teammate swears shadows detached from the wall...",
    "noise Adventurer's guild 32": "...and then they took a shape of a spike...",
    "noise Adventurer's guild 33": "...one thrust, and the floor boss was gone...",
    "noise Adventurer's guild 34": "Okay, so like, imagine a kobold...",
    "noise Adventurer's guild 35": "Okay, and now, imagine three kobolds. In a trenchcoat...",
    "noise Adventurer's guild 36": "That's a classic, right?",
    "noise Adventurer's guild 37": "Now imagine three fat rats in a trenchcoat, pretending to be a kobold",
    "noise Adventurer's guild 38": "And now... Imagine three of those, too dumb to realize they are all the same...",
    "noise Adventurer's guild 39": "Standing on top of one another, wearing one larger trenchcoat...",
    "noise Adventurer's guild 40": "No, I'm serious!",
    "noise Adventurer's guild 41": "I swear, my cousin's brother's dog's groomer's aunt's husband saw it happen with his own eyes!",
    "noise Adventurer's guild 42": "...but you know the craziest thing?",
    "noise Adventurer's guild 43": "I swear that two of them had cat tails...",
    "noise Adventurer's guild 44": "I wasn't drunk, they had cat tails and cat ears...",
    "noise Adventurer's guild 45": "...the other two seemed human though",
    "noise Adventurer's guild 46": "It was two nekomimi, boy and girl...",
    "noise Adventurer's guild 47": "...and then also two humans were with them...",
    "noise Adventurer's guild 48": "...I really don't get how they aren't famous yet, but...",
    "noise Adventurer's guild 49": "...I really think they could even fight HER...",
    "noise Adventurer's guild 50": "...yes, of course as a team and not alone...",
    "noise Adventurer's guild 51": "...too bad she retired to who knows where.",
    "noise Mages guild 1": "*A page turns somewhere above you*",
    "noise Mages guild 2": "*Something small and bright crosses a doorway and does not come back*",
    "noise Mages guild 3": "...no, read it again, the second line is the whole problem...",
    "noise Mages guild 4": "*The air goes cold for exactly one breath*",
    "noise Mages guild 5": "Who moved the chalk?",
    "noise Mages guild 6": "*A quill writes on by itself for a moment after being set down*",
    "noise Mages guild 7": "...silver, yes, but it has to be worked silver, ore is no use to anyone...",
