    "action rappel waterfall starting": "Try to rappel down the cliffside next to the waterfall",
    "action rappel waterfall desc": "It doesn't look that difficult, but it's still a strenuous task that will require some good long rope and proficiency in climbing, together with a fit physique. It will take a great deal of time, so make sure to prepare yourself for the task ahead",
    "action rappel waterfall during": "Rappelling down the cliff",
    "action rappel waterfall success": "It was slow, methodical work, but you've managed to secure a safe and stable pathway across the cliff face. That should make subsequent trips back up and down significantly faster in the future",
